// Runnable demo with multiple package-private classes (one file for brevity).
package com.bank.kafkause.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class KafkaUseCaseDemo {
    private static final Logger log = Logger.getLogger(KafkaUseCaseDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        KafkaUseCaseRouter router = new KafkaUseCaseRouter(
                new FraudStreamHandler(),
                new AuditLogHandler(),
                new NotificationHandler(),
                new WarehousePipelineHandler());

        BankEvent transfer = new BankEvent("TXF-00001", "SAV2001", "CUR3001",
                new BigDecimal("50000"), "TRANSFER");
        log.info(() -> "One event published to topic transactions: " + transfer.getEventId());
        router.fanOut(transfer);
    }
}

// ─── Would be in BankEvent.java ───
class BankEvent {
    private final String eventId, fromAccount, toAccount, type;
    private final BigDecimal amount;
    BankEvent(String eventId, String fromAccount, String toAccount,
              BigDecimal amount, String type) {
        this.eventId = eventId; this.fromAccount = fromAccount;
        this.toAccount = toAccount; this.amount = amount; this.type = type;
    }
    String getEventId() { return eventId; }
    String getFromAccount() { return fromAccount; }
    String getToAccount() { return toAccount; }
    BigDecimal getAmount() { return amount; }
    String getType() { return type; }
}

// ─── Would be in KafkaUseCase.java ───
enum KafkaUseCase {
    REAL_TIME_STREAMING, LOG_AGGREGATION, EVENT_DRIVEN_MICROSERVICES,
    PUB_SUB, BIG_DATA_PIPELINE, CDC, REPLICATION, CONTENT_DELIVERY
}

// ─── Would be in KafkaUseCaseRouter.java ───
class KafkaUseCaseRouter {
    private static final Logger log = Logger.getLogger(KafkaUseCaseRouter.class.getName());
    private final FraudStreamHandler fraud;
    private final AuditLogHandler audit;
    private final NotificationHandler notify;
    private final WarehousePipelineHandler warehouse;

    KafkaUseCaseRouter(FraudStreamHandler fraud, AuditLogHandler audit,
                       NotificationHandler notify, WarehousePipelineHandler warehouse) {
        this.fraud = fraud; this.audit = audit;
        this.notify = notify; this.warehouse = warehouse;
    }

    // One durable event, many independent consumer groups react — core Kafka strength
    void fanOut(BankEvent event) {
        log.fine(() -> "Fanning out event " + event.getEventId()
                + " to all consumer groups");
        fraud.onEvent(event);        // REAL_TIME_STREAMING
        audit.onEvent(event);        // LOG_AGGREGATION
        notify.onEvent(event);       // PUB_SUB
        warehouse.onEvent(event);    // BIG_DATA_PIPELINE
    }
}

// ─── Would be in FraudStreamHandler.java ───
class FraudStreamHandler {
    private static final Logger log = Logger.getLogger(FraudStreamHandler.class.getName());
    void onEvent(BankEvent e) {
        if (e.getAmount().compareTo(new BigDecimal("100000")) > 0) {
            log.warning(() -> "FRAUD(real-time) high-value " + e.getAmount()
                    + " on " + e.getFromAccount());
        } else {
            log.info(() -> "FRAUD(real-time) checked " + e.getEventId() + " OK");
        }
    }
}

// ─── Would be in AuditLogHandler.java ───
class AuditLogHandler {
    private static final Logger log = Logger.getLogger(AuditLogHandler.class.getName());
    void onEvent(BankEvent e) {
        log.info(() -> "AUDIT(log-aggregation) stored " + e.getType()
                + " " + e.getFromAccount() + "->" + e.getToAccount());
    }
}

// ─── Would be in NotificationHandler.java ───
class NotificationHandler {
    private static final Logger log = Logger.getLogger(NotificationHandler.class.getName());
    void onEvent(BankEvent e) {
        log.info(() -> "NOTIFY(pub-sub) SMS to " + e.getFromAccount()
                + ": debited " + e.getAmount());
    }
}

// ─── Would be in WarehousePipelineHandler.java ───
class WarehousePipelineHandler {
    private static final Logger log = Logger.getLogger(WarehousePipelineHandler.class.getName());
    void onEvent(BankEvent e) {
        log.info(() -> "WAREHOUSE(big-data) buffered " + e.getEventId()
                + " for nightly load + mirrored to DR region");
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
